mapper.select:
select pp.supplier_id, s.name as supplierName, ppd.currency, ppd.tax_price as taxPrice, ppd.tax_rate * 100 as taxRate, ppd.min_qty as minQty, ppd.max_qty as maxQty, ppd.delivery_day as deliveryDay from purchase_price pp inner join purchase_price_detail ppd on pp.id = ppd.purchase_price_id and ppd.is_deleted = false inner join supplier s on pp.supplier_id = s.id and s.is_deleted = false
pp.is_deleted = false and pp.approve_status = 'approve' and ppd.disabled = false and now() >= ppd.effective_date and ppd.expire_date >= now()
and ppd.sku_id = #{params.skuId}
and ppd.max_qty > #{params.purchaseQty} and #{params.purchaseQty} >= ppd.min_qty
and pp.supplier_id = #{params.supplierId}

SELECT sku_id, delivery_day, min_qty, max_qty, currency, tax_price, tax_rate, disabled FROM purchase_price_detail WHERE is_deleted=FALSE AND purchase_price_id IN ( SELECT id FROM purchase_price WHERE supplier_id=#{supplierId} AND is_deleted=FALSE
AND approve_status IN
#{status}
)
AND id NOT IN
#{id}
AND sku_id IN
#{skuId}

SELECT sku_id, delivery_day, min_qty, max_qty, currency, tax_price, tax_rate, disabled, supplier_id FROM purchase_price_detail WHERE is_deleted=FALSE AND purchase_price_id IN ( SELECT id FROM purchase_price WHERE is_deleted=FALSE
AND supplier_id IN
#{supplierId}
AND approve_status IN
#{status}
)
AND id NOT IN
#{id}
AND sku_id IN
#{skuId}

SELECT ppd.id, ppd.sku_id, ppd.delivery_day, ppd.min_qty, ppd.max_qty, ppd.currency, ppd.tax_price, ppd.tax_rate, ppd.disabled, pp.approve_status FROM purchase_price_detail ppd inner join purchase_price pp on pp.id = ppd.purchase_price_id WHERE ppd.is_deleted=FALSE AND pp.is_deleted=FALSE and pp.supplier_id = #{supplierId}
AND pp.approve_status IN
#{status}

SELECT ppd.id, ppd.create_user_id, ppd.create_user_name, ppd.create_time, ppd.update_user_id, ppd.update_user_name, ppd.update_time, ppd.version, ppd.is_deleted, ppd.sku_id, ppd.purchase_price_id, ppd.sku_no, ppd.product_name, ppd.min_qty, ppd.max_qty, ppd.currency, ppd.tax_price, ppd.expire_date, ppd.tax_rate, ppd.delivery_day, ppd.effective_date, ppd.disabled, ppd.kingdee_detail_id, ppd.remark, ppd.supplier_id FROM purchase_price_detail ppd inner join purchase_price pp on pp.id = ppd.purchase_price_id WHERE ppd.is_deleted=FALSE AND pp.is_deleted=FALSE
AND pp.id IN
#{purchasePriceId}
